use std::collections::HashMap;struct RandomizedSet{a:Vec<i32>,m:HashMap<i32,usize>}impl RandomizedSet{fn new()->Self{Self{a:vec![],m:HashMap::new()}}fn insert(&mut self,v:i32)->bool{if self.m.contains_key(&v){return false}self.m.insert(v,self.a.len());self.a.push(v);true}fn remove(&mut self,v:i32)->bool{let Some(&i)=self.m.get(&v)else{return false};let x=*self.a.last().unwrap();self.a[i]=x;self.m.insert(x,i);self.a.pop();self.m.remove(&v);true}fn get_random(&self)->i32{self.a[fastrand::usize(..self.a.len())]}}
